use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct User {
    pub id: u64,
    pub name: String,
    pub email: String,
}

// Payload received when creating a new user (ID is generated by the server)
#[derive(Deserialize, Serialize, Debug)]
pub struct CreateUserRequest {
    pub name: String,
    pub email: String,
}